+  if (typeof input.score !== "number" || !Number.isSafeInteger(input.score) || input.score < 0 || input.score > MAX_SCORE) return null;
+  if (!ENDINGS.some((ending) => ending === input.ending) || !MASKS.some((mask) => mask === input.mask)) return null;
