+    submissionId: input.submissionId.toLowerCase(),
+    initials: BLOCKED_INITIALS.has(initials) ? "???" : initials,
+    score: input.score,
+    ending: input.ending as ScoreSubmission["ending"],
+    mask: input.mask as ScoreSubmission["mask"],
+  };
